### C++ Code Example

In C++, you could create a simple class to represent a mode of transportation and a function to print available routes.

```cpp
#include <iostream>
#include <vector>
#include <string>

class Transportation {
public:
    std::string name;
    int duration; // in hours

    Transportation(std::string n, int d) : name(n), duration(d) {}

    void printDetails() const {
        std::cout << "Transportation: " << name << ", Duration: " << duration << " hours" << std::endl;
    }
};

void findTransportOptions(Transportation* transOptions[], int numOptions) {
    for (int i = 0; i < numOptions; ++i) {
        transOptions[i]->printDetails();
    }
