    {
        // Sample JSON string with no data
        string json = "{}";

        // Deserialize the JSON string into a dictionary
        Dictionary<string, string> dictionary = JsonConvert.DeserializeObject<Dictionary<string, string>>(json);

        // Check if the dictionary is empty
        if (dictionary.Count == 0)
        {
            Console.WriteLine("The dictionary is empty.");
        }
        else
        {
            foreach (var item in dictionary)
            {
                Console.WriteLine($"Key: {item.Key}, Value: {item.Value}");
            }
        }
    }
}
```

In this example, the `json` string is an empty object (`{}`). When we call `JsonConvert.DeserializeObject<Dictionary<string, string>>`, the resulting dictionary `dictionary` will be empty, and the output will be "The dictionary is empty."

If the JSON contains key-value pairs, they will be deserialized into the dictionary correctly. For example:

```csharp
string jsonWithData = "{\"key1\":\"value1\", \"key2\":\"value2\"}";

Dictionary<string, string> dictionaryWithData = JsonConvert.DeserializeObject<Dictionary<string, string>>(jsonWithData);

