        for (uint256 i = 0; i < amountsToTransfer.length(); i++) {
            address recipient = amountsToTransfer.keys(i);
            uint256 amount = amountsToTransfer[recipient];
            totalAmount += amount;
        }

        require(totalAmount <= msg.value, "Insufficient Ether to complete transfers");

        // Transfer the Ether to each recipient
        for (uint256 i = 0; i < amountsToTransfer.length(); i++) {
            address recipient = amountsToTransfer.keys(i);
            uint256 amount = amountsToTransfer[recipient];

