Below is a TypeScript script that uses `fetch` to monitor network requests and logs the URLs of each API call. Note that this script should be run in an environment where the browser's developer tools are accessible and the `fetch` API is available (most modern browsers).

```typescript
// This script logs the APIs a website uses.
// It uses the browser's Fetch API to monitor network requests.

interface NetworkRequest {
    url: string;
    method: string;
}

const observer = new MutationObserver((mutations) => {
    mutations.forEach((mutation) => {
        if (mutation.type === 'childList') {
            mutation.addedNodes.forEach((node) => {
                if (node instanceof HTMLElement && node.tagName.toLowerCase() === 'img' || node.tagName.toLowerCase() === 'script') {
                    const url = node.getAttribute('src') || node.getAttribute('srcdoc') || node.getAttribute('href');
                    if (url) {
                        console.log(`Detected network request: ${url}`);
                    }
                } else if (node.tagName.toLowerCase() === 'link') {
                    const url = node.getAttribute('href');
                    if (url) {
                        console.log(`Detected network request: ${url}`);
                    }
                }
            });
        }
    });
});

observer.observe(document.body, { childList: true, subtree: true });

function logNetworkRequests(event: ProgressEvent<EventTarget>) {
    const response = event.target as XMLHttpRequest;
    if (!response) return;

    // Only log when the request finishes
    if (response.readyState === 4) {
        const url = new URL(response.responseURL);
        console.log(`Completed network request: ${url.href}`);
    }
}

// Add event listener to XMLHttpRequests
if (window.XMLHttpRequest) {
    XMLHttpRequest.prototype.addEventListener('progress', logNetworkRequests, false);
}

// Add event listener to fetch API
if (typeof fetch === 'function') {
    Object.defineProperty(fetch, 'addEventListener', {
        value: function(name: string, callback: (event: ProgressEvent<EventTarget>) => void): void {
            if (name !== 'progress') return;
            this.addEventListener('progress', event => {
                const response = event.target as XMLHttpRequest;
                if (!response) return;
                if (response.readyState === 4) {
                    const url = new URL(response.responseURL);
                    console.log(`Completed network request: ${url.href}`);
                    callback(event);
                }
            }, false);
        },
        writable: true,
        enumerable: false,
        configurable: true
    });
}
```

