import puppeteer from 'puppeteer';
import axios from 'axios';
import { promisify } from 'util';

// Promise version of setTimeout
const psetTimeout = promisify(setTimeout);

async function detectApis(url: string): Promise<string[]> {
    // Launch Puppeteer browser
    const browser = await puppeteer.launch();
    const page = await browser.newPage();

    // Navigate to the website
    await page.goto(url);

    // Get all links on the page
    let urls = await getAllLinks(page);
    console.log(`Found ${urls.length} links`);

    // Filter out JavaScript-based endpoints (which are often API endpoints)
    urls = await filterPotentialApiUrls(urls);

    // Visit each URL and check if it's an API endpoint
    const apiEndpoints = await visitAndCheckEndpoints(urls, url);

    // Clean up
    await browser.close();

    return apiEndpoints;
}

async function getAllLinks(page: puppeteer.Page): Promise<string[]> {
    const links = await page.evaluate(() => {
        const links = Array.from(document.querySelectorAll('a[href]')).map(a => a.href);
        return links;
    });

    return links.map(link => new URL(link, page.url()).href);
}

async function filterPotentialApiUrls(urls: string[]): Promise<string[]> {
    return urls.filter(url => {
        // Heuristic: remove URLs that end with common HTML file extensions
        const htmlExtensions = ['html', 'htm', 'xhtml'];
        return !htmlExtensions.some(ext => url.endsWith('.' + ext));
    });
}

