    super.onTimeTick();
    long currentTime = System.currentTimeMillis();
    Calendar calendar = Calendar.getInstance();
    calendar.setTimeInMillis(currentTime);
    updateTextOnWatch(calendar);
}

private void updateTextOnWatch(Calendar calendar) {
