    publishMessage();
  }
}

void reconnect() {
  // Loop until we're reconnected
  while (!client.connected()) {
    Serial.print("Attempting MQTT connection...");
    // Attempt to connect
    if (client.connect("ESP8266Client")) {
      Serial.println("connected");
      // Once connected, publish an announcement...
      client.publish(pubTopic, "Hello, I'm connected!");
    } else {
      Serial.print("failed, rc=");
      Serial.print(client.state());
      Serial.println(" try again in 5 seconds");
      // Wait 5 seconds before retrying
      delay(5000);
    }
  }
}

void publishMessage() {
  client.publish(pubTopic, msgBuffer);
}
```

### Explanation:
1. **WiFi Connection**: The ESP8266 first connects to the specified WiFi network.
2. **MQTT Client Initialization**: The `PubSubClient` is initialized with the WiFi client.
3. **Reconnect Function**: A function `reconnect()` handles the reconnection logic. If the client loses its connection to the MQTT broker, it attempts to reconnect every 5 seconds.
4. **Message Publishing**: The `publishMessage()` function sends a message to the specified topic every 5 seconds.

Make sure to replace `"your_SSID"` and `"your_PASSWORD"` with your actual WiFi credentials. Also, update the `mqtt_server` variable with the IP address or domain name of your MQTT broker.

This example provides a basic structure for handling non-blocking MQTT connections. You can expand upon it by adding more functionality like subscribing to topics, handling incoming messages, and more
